settings.custom_liquid:
{% comment %}
  Custom Liquid Button for Pouch Size Quiz
  Add this code where you want the button to appear
{% endcomment %}

<div class="quiz-button-container">
  <style>
    .quiz-button-container {
      padding: 20px 0;
      display: flex;
      align-items: center;
      justify-content: flex-start;
      gap: 20px;
    }

    .quiz-text {
      font-size: 16px;
      color: #4a4a4a;
    }

    .quiz-button {
      display: inline-block;
      padding: 12px 24px;
      background-color: #3a75c2;
      color: white;
      text-decoration: none;
      border-radius: 4px;
      font-weight: 500;
      transition: background-color 0.3s ease;
    }

    .quiz-button:hover {
      background-color: #2e5d9c;
      color: white;
    }
  </style>

  <div class="quiz-text">What's My Pouch Size?</div>
  <a href="#open-quiz-tools/perfect-product-finder/perfect-underwear-fit-quiz" class="quiz-button">
    Take the Best Fit Quiz
  </a>
</div>
